var sync = require('./sync')
  , syncAll = require('./syncAll')
  , search = require('./search')
  , helpers = require('./helpers')
  , elasticsearch = require('elasticsearch');


var configOptions = {};

/**
 * Attach mongoose plugin for elasticsearch indexing
 *
 * @param  {Object} schema      mongoose schema
 * @param  {Object} options
 */
module.exports = exports = function (schema, options) {

  schema.methods.unindex = unindex;

  schema.statics.syncAll = function (cb) {

    return syncAll.call(this, schema, options, cb)
  }

  schema.methods.sync = function (cb) {

    return sync.call(this, schema, options, cb)
  }

  schema.statics.search = function (searchOpts, cb) {

    return search.call(this, schema, searchOpts, options, cb);
  }

  schema.post('remove', function () {
    this.unindex(options)
  })
}

/*
  Global search.
 */
exports.search = function (searchOptions, cb) {

  var client = elasticsearch.Client({ host: configOptions.host })

  // merge `options` with default user-level search options
  var options = helpers.mergeSearchOptions(searchOptions)

  // merge the body
  var body = helpers.mergeSearchBody(options)

  // setup
  var type = searchOptions.collections || ['_all'];
  var index = (configOptions.prefix)
    ? configOptions.prefix + '-' + type[0]
    : type;


  var search = {
    index: index,
    type:  type,
    body: body
  }

  client.search(search, function(err, results) {
    if (err) {
      return cb(err)
    }

    if (searchOptions.raw) {
      return cb (null, results);
    }

    results = helpers.reduce(results);

    return cb(null, results);
  })
}

/*
  Configuration for the global search.
 */
exports.search.config = function (options) {
  configOptions = options;
}

function unindex (options) {
  var client = elasticsearch.Client({ host: options.host });

  // setup
  var type = this.constructor.modelName;
  var index = (options.prefix)
    ? options.prefix + '-' + type
    : type;

  var doc = helpers.mergeMapping(this, options.mapping)

  client.delete({
    index: index,
    type: type,
    id: this.id,
    body: doc
  }, function(err, res) {
  })
}

